  let b=studio_row(pixel,t.x,side,offset,smoothing);
  let c=studio_row(pixel+vec2<i32>(0,1),t.x,side,offset,smoothing);
  let d=studio_row(pixel+vec2<i32>(0,2),t.x,side,offset,smoothing);
