    let east=segments*.25;
    let west=segments*.75;
    let back=segments*.5;
    let x=studio_row(vec2<i32>(0,ring),0.0,side,offset,smoothing).x-
      studio_row(vec2<i32>(i32(back),ring),fract(back),side,offset,smoothing).x;
